import java.util.*;
import java.math.*;

public class Main {
    static final long MAX_NUM = 1234567890L;
    static final double epsilon = 1e-8;
    static final int pattern = 9;
    static final double pi = 3.14159265358979323846;

    public static long modPow(long base, long exp, long mod) {
        long result = 1;
        long cur = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * cur) % mod;
            }
            cur = (cur * cur) % mod;
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        long mod = sc.nextLong();

        long[] fac = new long[N + 1];
        long[] inv_fac = new long[N + 1];

        fac[0] = 1;
        inv_fac[0] = 1;

        for (int i = 1; i <= N; i++) {
            fac[i] = (fac[i - 1] * i) % mod;
            inv_fac[i] = (inv_fac[i - 1] * modPow(i, mod - 2, mod)) % mod;
        }

        long[] cnt = new long[M + 1];
        long[] sum = new long[M + 1];

        Arrays.fill(cnt, 0);
        Arrays.fill(sum, 0);
        cnt[0] = 1;

        for (int m = 1; m <= M; m++) {
            for (int k = 0; k < m; k++) {
                long c_left = (cnt[k] * inv_fac[k]) % mod;
                long c_right = (cnt[m - 1 - k] * inv_fac[m - 1 - k]) % mod;
                long s_left = (sum[k] * inv_fac[k]) % mod;
                long s_right = (sum[m - 1 - k] * inv_fac[m - 1 - k]) % mod;

                cnt[m] = (cnt[m] + c_left * c_right % mod * (m + 1)) % mod;

                long temp1 = (s_left * c_right) % mod;
                long temp2 = (c_left * s_right) % mod;
                long temp3 = (s_left * s_right) % mod;
                long sum_add = (temp1 + temp2 + temp3) % mod;
                sum[m] = (sum[m] + sum_add * (m + 1)) % mod;

                long numerator = k * (k + 1) + (m - k) * (m - k - 1);
                long term = (c_left * c_right) % mod * (numerator / 2) % mod;
                sum[m] = (sum[m] + term) % mod;
            }
            cnt[m] = (cnt[m] * fac[m - 1]) % mod;
            sum[m] = (sum[m] * fac[m - 1]) % mod;
        }

        long[][] cnt_ans = new long[N + 1][M + 1];
        long[][] sum_ans = new long[N + 1][M + 1];

        for (int i = 0; i <= N; i++) {
            Arrays.fill(cnt_ans[i], 0);
            Arrays.fill(sum_ans[i], 0);
        }

        cnt_ans[0][0] = 1;

        for (int i = 1; i <= N; i++) {
            for (int j = 0; j <= Math.min(i, M); j++) {
                cnt_ans[i][j] = cnt_ans[i - 1][j];
                sum_ans[i][j] = sum_ans[i - 1][j];

                if (j == i) {
                    cnt_ans[i][j] = (cnt_ans[i][j] + cnt[i] * inv_fac[i]) % mod;
                    sum_ans[i][j] = (sum_ans[i][j] + sum[i] * inv_fac[i]) % mod;
                }

                for (int k = 1; k <= Math.min(j, i - 1); k++) {
                    long c = (cnt[k] * inv_fac[k]) % mod;
                    long s = (sum[k] * inv_fac[k]) % mod;

                    cnt_ans[i][j] = (cnt_ans[i][j] + cnt_ans[i - 1 - k][j - k] * c) % mod;
                    long temp_sum = (sum_ans[i - 1 - k][j - k] * c + cnt_ans[i - 1 - k][j - k] * s) % mod;
                    sum_ans[i][j] = (sum_ans[i][j] + temp_sum) % mod;
                }
            }
        }

        long final_res = (sum_ans[N][M] * fac[M]) % mod;
        System.out.println(final_res);
        sc.close();
    }
}
